        "02-explain" to linkedMapOf(
            "csv.js" to "// Reads CSV text into rows of fields. Quoted fields may hold commas and doubled quotes.\nfunction parseCSV(text) {\n  const rows = [];\n  let row = [], field = '', quoted = false;\n  for (let i = 0; i < text.length; i++) {\n    const c = text[i];\n    if (quoted) {\n      if (c === '\"' && text[i + 1] === '\"') { field += '\"'; i++; }\n      else if (c === '\"') quoted = false;\n      else field += c;\n    } else if (c === '\"') quoted = true;\n    else if (c === ',') { row.push(field); field = ''; }\n    else if (c === '\\n') { row.push(field); rows.push(row); row = []; field = ''; }\n    else field += c;\n  }\n  if (field || row.length) { row.push(field); rows.push(row); }\n  return rows;\n}\nmodule.exports = { parseCSV };\n"
        ),
        "03-todo-feature" to linkedMapOf(
            "app.js" to "const list = document.getElementById('list');\nconst input = document.getElementById('new');\nlet items = [];\n\nfunction render() {\n  list.innerHTML = '';\n  items.forEach((it, i) => {\n    const li = document.createElement('li');\n    li.textContent = it.text;\n    if (it.done) li.className = 'done';\n    li.onclick = () => { items[i].done = !items[i].done; render(); };\n    list.appendChild(li);\n  });\n}\n\ndocument.getElementById('add').onclick = () => {\n  const t = input.value.trim();\n  if (!t) return;\n  items.push({ text: t, done: false });\n  input.value = '';\n  render();\n};\n\nrender();\n",
            "index.html" to "<!DOCTYPE html>\n<html>\n<head><meta charset=\"utf-8\"><title>Todo</title><link rel=\"stylesheet\" href=\"style.css\"></head>\n<body>\n  <h1>Todo</h1>\n  <input id=\"new\" placeholder=\"What to do\">\n  <button id=\"add\">Add</button>\n  <ul id=\"list\"></ul>\n  <script src=\"app.js\"></script>\n</body>\n</html>\n",
